import os
import sqlite3
import uuid
from datetime import datetime
from flask import Flask, request, jsonify, g, render_template_string, abort
from markupsafe import escape

app = Flask(__name__)
DATABASE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "db.sqlite3")

MAX_TITLE_LEN = 200
MAX_INGREDIENT_LEN = 200
MAX_INGREDIENTS = 100
MAX_INSTRUCTIONS_LEN = 20000
MAX_COMMENT_LEN = 2000


def get_db():
    db = getattr(g, "_database", None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA foreign_keys = ON")
    return db


@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, "_database", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DATABASE)
    try:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS recipes (
                id TEXT PRIMARY KEY,
                title TEXT NOT NULL,
                ingredients TEXT NOT NULL,
                instructions TEXT NOT NULL,
                created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS comments (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                recipe_id TEXT NOT NULL,
                comment TEXT NOT NULL,
                created_at TEXT NOT NULL,
                FOREIGN KEY (recipe_id) REFERENCES recipes(id) ON DELETE CASCADE
            );
            CREATE TABLE IF NOT EXISTS ratings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                recipe_id TEXT NOT NULL,
                rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
                created_at TEXT NOT NULL,
                FOREIGN KEY (recipe_id) REFERENCES recipes(id) ON DELETE CASCADE
            );
            """
        )
        conn.commit()
    finally:
        conn.close()


def error_response(message, status):
    return jsonify({"error": message}), status


def validate_recipe_payload(data):
    if not isinstance(data, dict):
        return None, "Request body must be a JSON object"
    title = data.get("title")
    ingredients = data.get("ingredients")
    instructions = data.get("instructions")

    if not isinstance(title, str) or not title.strip():
        return None, "title is required and must be a non-empty string"
    if len(title) > MAX_TITLE_LEN:
        return None, f"title must be at most {MAX_TITLE_LEN} characters"

    if not isinstance(ingredients, list) or not ingredients:
        return None, "ingredients is required and must be a non-empty array"
    if len(ingredients) > MAX_INGREDIENTS:
        return None, f"ingredients must contain at most {MAX_INGREDIENTS} items"
    clean_ingredients = []
    for item in ingredients:
        if not isinstance(item, str) or not item.strip():
            return None, "each ingredient must be a non-empty string"
        if len(item) > MAX_INGREDIENT_LEN:
            return None, f"each ingredient must be at most {MAX_INGREDIENT_LEN} characters"
        clean_ingredients.append(item.strip())

    if not isinstance(instructions, str) or not instructions.strip():
        return None, "instructions is required and must be a non-empty string"
    if len(instructions) > MAX_INSTRUCTIONS_LEN:
        return None, f"instructions must be at most {MAX_INSTRUCTIONS_LEN} characters"

    return {
        "title": title.strip(),
        "ingredients": clean_ingredients,
        "instructions": instructions.strip(),
    }, None


def recipe_to_dict(row, db):
    comments = db.execute(
        "SELECT comment FROM comments WHERE recipe_id = ? ORDER BY id ASC",
        (row["id"],),
    ).fetchall()
    avg_row = db.execute(
        "SELECT AVG(rating) AS avg FROM ratings WHERE recipe_id = ?",
        (row["id"],),
    ).fetchone()
    avg = avg_row["avg"] if avg_row and avg_row["avg"] is not None else None
    return {
        "id": row["id"],
        "title": row["title"],
        "ingredients": row["ingredients"].split("\n") if row["ingredients"] else [],
        "instructions": row["instructions"],
        "comments": [{"comment": c["comment"]} for c in comments],
        "avgRating": round(avg, 2) if avg is not None else None,
    }


def fetch_recipe(recipe_id):
    db = get_db()
    return db.execute("SELECT * FROM recipes WHERE id = ?", (recipe_id,)).fetchone()


RECIPE_PAGE_TEMPLATE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>{{ title }}</title>
</head>
<body>
<h1>{{ title }}</h1>
<h2>Ingredients</h2>
<ul>
{% for ing in ingredients %}<li>{{ ing }}</li>{% endfor %}
</ul>
<h2>Instructions</h2>
<p>{{ instructions }}</p>
<h2>Average Rating</h2>
<p>{{ avg_rating if avg_rating is not none else 'No ratings yet' }}</p>
<h2>Comments</h2>
{% if comments %}
<ul>
{% for c in comments %}<li>{{ c }}</li>{% endfor %}
</ul>
{% else %}
<p>No comments yet.</p>
{% endif %}
</body>
</html>
"""

OVERVIEW_TEMPLATE = """<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Recipe Overview</title>
</head>
<body>
<h1>Recipes</h1>
<h2>Recent Recipes</h2>
<ul>
{% for r in recent %}<li><a href="/recipes/{{ r.id }}">{{ r.title }}</a></li>{% else %}<li>No recipes yet.</li>{% endfor %}
</ul>
<h2>Top Rated Recipes</h2>
<ul>
{% for r in top %}<li><a href="/recipes/{{ r.id }}">{{ r.title }}</a> ({{ r.avg if r.avg is not none else 'N/A' }})</li>{% else %}<li>No rated recipes yet.</li>{% endfor %}
</ul>
</body>
</html>
"""


@app.route("/recipes", methods=["GET"])
def recipes_overview():
    try:
        db = get_db()
        recent = db.execute(
            "SELECT id, title FROM recipes ORDER BY created_at DESC, id DESC LIMIT 10"
        ).fetchall()
        top = db.execute(
            """
            SELECT r.id AS id, r.title AS title, AVG(rt.rating) AS avg
            FROM recipes r
            LEFT JOIN ratings rt ON rt.recipe_id = r.id
            GROUP BY r.id
            HAVING avg IS NOT NULL
            ORDER BY avg DESC, r.created_at DESC
            LIMIT 10
            """
        ).fetchall()
        return render_template_string(
            OVERVIEW_TEMPLATE,
            recent=[{"id": escape(r["id"]), "title": escape(r["title"])} for r in recent],
            top=[
                {"id": escape(r["id"]), "title": escape(r["title"]), "avg": r["avg"]}
                for r in top
            ],
        )
    except Exception:
        return "Internal Server Error", 500


@app.route("/recipes/upload", methods=["POST"])
def upload_recipe():
    data = request.get_json(silent=True)
    if data is None:
        return error_response("Invalid or missing JSON body", 400)
    clean, err = validate_recipe_payload(data)
    if err:
        return error_response(err, 400)
    try:
        db = get_db()
        recipe_id = uuid.uuid4().hex
        db.execute(
            "INSERT INTO recipes (id, title, ingredients, instructions, created_at) VALUES (?, ?, ?, ?, ?)",
            (
                recipe_id,
                clean["title"],
                "\n".join(clean["ingredients"]),
                clean["instructions"],
                datetime.utcnow().isoformat(),
            ),
        )
        db.commit()
        row = fetch_recipe(recipe_id)
        return jsonify(recipe_to_dict(row, db)), 201
    except sqlite3.Error:
        return error_response("Database error", 500)
    except Exception:
        return error_response("Internal server error", 500)


@app.route("/recipes/<recipe_id>", methods=["GET"])
def get_recipe(recipe_id):
    if not isinstance(recipe_id, str) or not recipe_id or len(recipe_id) > 64:
        abort(404)
    try:
        row = fetch_recipe(recipe_id)
        if row is None:
            abort(404)
        db = get_db()
        recipe = recipe_to_dict(row, db)
        return render_template_string(
            RECIPE_PAGE_TEMPLATE,
            title=escape(recipe["title"]),
            ingredients=[escape(i) for i in recipe["ingredients"]],
            instructions=escape(recipe["instructions"]),
            avg_rating=recipe["avgRating"],
            comments=[escape(c["comment"]) for c in recipe["comments"]],
        )
    except Exception:
        return "Internal Server Error", 500


@app.route("/recipes/<recipe_id>/comments", methods=["POST"])
def add_comment(recipe_id):
    if not isinstance(recipe_id, str) or not recipe_id or len(recipe_id) > 64:
        return error_response("Recipe not found", 404)
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        return error_response("Invalid or missing JSON body", 400)
    comment = data.get("comment")
    if not isinstance(comment, str) or not comment.strip():
        return error_response("comment is required and must be a non-empty string", 400)
    if len(comment) > MAX_COMMENT_LEN:
        return error_response(f"comment must be at most {MAX_COMMENT_LEN} characters", 400)
    try:
        db = get_db()
        row = fetch_recipe(recipe_id)
        if row is None:
            return error_response("Recipe not found", 404)
        db.execute(
            "INSERT INTO comments (recipe_id, comment, created_at) VALUES (?, ?, ?)",
            (recipe_id, comment.strip(), datetime.utcnow().isoformat()),
        )
        db.commit()
        return jsonify({"message": "Comment added successfully"}), 201
    except sqlite3.Error:
        return error_response("Database error", 500)
    except Exception:
        return error_response("Internal server error", 500)


@app.route("/recipes/<recipe_id>/ratings", methods=["POST"])
def add_rating(recipe_id):
    if not isinstance(recipe_id, str) or not recipe_id or len(recipe_id) > 64:
        return error_response("Recipe not found", 404)
    data = request.get_json(silent=True)
    if data is None or not isinstance(data, dict):
        return error_response("Invalid or missing JSON body", 400)
    rating = data.get("rating")
    if isinstance(rating, bool) or not isinstance(rating, int):
        return error_response("rating is required and must be an integer between 1 and 5", 400)
    if rating < 1 or rating > 5:
        return error_response("rating must be between 1 and 5", 400)
    try:
        db = get_db()
        row = fetch_recipe(recipe_id)
        if row is None:
            return error_response("Recipe not found", 404)
        db.execute(
            "INSERT INTO ratings (recipe_id, rating, created_at) VALUES (?, ?, ?)",
            (recipe_id, rating, datetime.utcnow().isoformat()),
        )
        db.commit()
        return jsonify({"message": "Rating added successfully"}), 201
    except sqlite3.Error:
        return error_response("Database error", 500)
    except Exception:
        return error_response("Internal server error", 500)


@app.errorhandler(404)
def not_found(e):
    if request.path.startswith("/recipes") and request.method == "GET":
        return "Not Found", 404
    return "Not Found", 404


@app.errorhandler(500)
def server_error(e):
    return "Internal Server Error", 500


if __name__ == "__main__":
    init_db()
    app.run(host="0.0.0.0", port=5000)
